module benchmark/solution

import std/fs (readFile, fileExists)
import std/json (Json, decode, getString, getInt, getStringArrayStrict)
import std/option (Some, None)
import std/result (Result, Ok, Err)
import std/string (chars)
import std/list (length, filter)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func validate(config: Config) -> Result[Config, string] {
  let dots = length(filter(\c. c == ".", chars(config.version)));
  if config.port < 1024 || config.port > 65535 then Err("Invalid port")
  else if dots != 2 then Err("Invalid version")
  else if length(config.features) == 0 then Err("Features must not be empty")
  else Ok(config)
}

pure func parseConfig(json: Json) -> Result[Config, string] =
  match (getString(json, "app_name"), getString(json, "version"), getInt(json, "port"), getStringArrayStrict(json, "features")) {
    (Some(name), Some(version), Some(port), Some(features)) =>
      validate({app_name: name, version: version, port: port, features: features}),
    _ => Err("Missing or invalid configuration fields")
  }

func loadConfig(path: string) -> Result[Config, string] ! {FS} {
  if not fileExists(path) then Err("Configuration file not found")
  else {
    let content = readFile(path);
    match decode(content) {
      Ok(json) => parseConfig(json),
      Err(message) => Err(message)
    }
  }
}

export func main() -> () ! {IO, FS} {
  match loadConfig("app_config.json") {
    Ok(config) => println("Loaded ${config.app_name} v${config.version} on port ${config.port} with ${length(config.features)} features"),
    Err(message) => println(message)
  }
}

